const MEDIA_URL = `${_utils_urls__WEBPACK_IMPORTED_MODULE_1__.DOMAIN_IMG}/img/galeria-imatges`;
// ============================================================
// GALERIA PÚBLICA
// ============================================================
async function galeriaImatgesPublica(slug) {
    const container = document.getElementById('GaleriaImatges');
    if (!container) {
        return;
    }
    container.innerHTML = '';
    try {
        // ==========================================================
        // OBTENER GALERÍA
        // ==========================================================
        const data = await _Infrastructure_Api_Client_ApiClient__WEBPACK_IMPORTED_MODULE_0__.api.get('public/imatges/get/galeriaImatgesId', {
            slug
        });
        // ==========================================================
        // ORDENAR IMÁGENES
        // ==========================================================
        const imatges = [
            ...data.imatges
        ].sort((a, b)=>a.ordre - b.ordre);
        // ==========================================================
        // TÍTULO
        // ==========================================================
        const titol = document.createElement('div');
        titol.className = 'mb-4';
        titol.innerHTML = `
      <h3>${escapeHtml(data.nom)}</h3>

      ${data.alt ? `
            <p class="text-muted">
              ${escapeHtml(data.alt)}
            </p>
          ` : ''}
    `;
        container.appendChild(titol);
        // ==========================================================
        // CONTENEDOR GALERÍA
        // ==========================================================
        const galeria = document.createElement('div');
        galeria.className = 'row g-3';
        // ==========================================================
        // SIN IMÁGENES
        // ==========================================================
        if (imatges.length === 0) {
            galeria.innerHTML = `
        <div class="col-12">
          <div class="alert alert-secondary">
            Aquesta galeria no conté cap imatge.
          </div>
        </div>
      `;
            container.appendChild(galeria);
            return;
        }
        // ==========================================================
        // IMÁGENES
        // ==========================================================
        imatges.forEach((imatge)=>{
            const imageUrl = `${MEDIA_URL}/` + `${encodeURIComponent(data.directori)}/` + `${encodeURIComponent(imatge.nameImg)}.` + `${encodeURIComponent(imatge.extension)}`;
            const alt = imatge.alt ?? imatge.nom;
            const col = document.createElement('div');
            col.className = 'col-6 col-md-4 col-lg-3';
            col.innerHTML = `
        <div class="card h-100">

          <a
            href="${escapeHtmlAttribute(imageUrl)}"
            class="galeria-imatge-link"
            data-bs-toggle="modal"
            data-bs-target="#modalGaleriaImatge"
            data-image="${escapeHtmlAttribute(imageUrl)}"
            data-alt="${escapeHtmlAttribute(alt)}"
          >

            <img
              src="${escapeHtmlAttribute(imageUrl)}"
              alt="${escapeHtmlAttribute(alt)}"
              class="card-img-top"
              style="
                height: 180px;
                object-fit: cover;
              "
            >

          </a>

          <div class="card-body">

            <h6 class="card-title mb-1">
              ${escapeHtml(imatge.nom)}
            </h6>

            ${imatge.alt ? `
                  <p class="card-text small text-muted mb-0">
                    ${escapeHtml(imatge.alt)}
                  </p>
                ` : ''}

          </div>

        </div>
      `;
            galeria.appendChild(col);
        });
        container.appendChild(galeria);
        // ==========================================================
        // MODAL
        // ==========================================================
        crearModalGaleria(container);
        // ==========================================================
        // EVENTOS MODAL
        // ==========================================================
        const modalImage = document.getElementById('modalGaleriaImatgeImg');
        if (!modalImage) {
            return;
        }
        const links = container.querySelectorAll('.galeria-imatge-link');
        links.forEach((link)=>{
            link.addEventListener('click', ()=>{
                const imageUrl = link.getAttribute('data-image');
                const alt = link.getAttribute('data-alt');
                if (!imageUrl) {
                    return;
                }
                try {
                    const url = new URL(imageUrl, window.location.origin);
                    if (url.protocol !== 'http:' && url.protocol !== 'https:') {
                        return;
                    }
                    modalImage.src = url.href;
                    modalImage.alt = alt ?? '';
                } catch  {
                // URL no válida
                }
            });
        });
    } catch (error) {
        /* eslint-disable */ console.error(...oo_tx(`3242513478_209_4_209_62_11`, 'Error obtenint la galeria pública:', error));
        container.innerHTML = `
      <div class="alert alert-danger">
        No s'ha pogut obtenir la galeria d'imatges.
      </div>
    `;
    }
}
// ============================================================
// CREAR MODAL
// ============================================================
function crearModalGaleria(container) {
    const modalExistente = document.getElementById('modalGaleriaImatge');
    if (modalExistente) {
        modalExistente.remove();
    }
    const modal = document.createElement('div');
    modal.id = 'modalGaleriaImatge';
    modal.className = 'modal fade';
    modal.tabIndex = -1;
    modal.setAttribute('aria-hidden', 'true');
    modal.innerHTML = `
    <div class="modal-dialog modal-xl modal-dialog-centered">

      <div class="modal-content">

        <div class="modal-header">

          <button
            type="button"
            class="btn-close"
            data-bs-dismiss="modal"
            aria-label="Tancar">
          </button>

        </div>

        <div class="modal-body text-center">

          <img
            id="modalGaleriaImatgeImg"
            src=""
            alt=""
            class="img-fluid"
            style="max-height: 80vh;"
          >

        </div>

      </div>

    </div>
  `;
    container.appendChild(modal);
}
