// ============================================================
// BLOQUE IMAGEN EXISTENTE
// ============================================================
function crearBloqueImatgeExistente(container, imatge, directori) {
    const index = container.children.length;
    const bloque = document.createElement('div');
    bloque.className = 'col-12';
    // ------------------------------------------------------------
    // URL imagen
    // ------------------------------------------------------------
    const imageUrl = `${MEDIA_URL}/` + `${encodeURIComponent(directori)}/` + `${encodeURIComponent(imatge.nameImg)}.` + `${imatge.extension}`;
    bloque.innerHTML = `

    <div class="card">

      <div class="card-header d-flex justify-content-between align-items-center">

        <strong>
          Imatge ${index + 1}
        </strong>

        <button
          type="button"
          class="btn btn-sm btn-outline-danger btnEliminarImatge">
          Eliminar
        </button>

      </div>


      <div class="card-body row g-3">


        <!-- ================================================== -->
        <!-- ID IMAGEN -->
        <!-- ================================================== -->

        <input
          type="hidden"
          name="imatges[${index}][id]"
          value="${escapeHtmlAttribute(imatge.id)}">


        <!-- ================================================== -->
        <!-- MINIATURA -->
        <!-- ================================================== -->

        <div class="col-12">

          <div class="small text-muted mb-2">
            Imatge actual:
          </div>

          <div>

            <img
              src="${imageUrl}"
              alt="${escapeHtmlAttribute(imatge.alt ?? imatge.nom)}"
              class="img-thumbnail"
              style="
                max-width: 250px;
                max-height: 180px;
                object-fit: contain;
              ">

          </div>

        </div>


        <!-- ================================================== -->
        <!-- ARCHIVO -->
        <!-- ================================================== -->

        <div class="col-12">

          <div class="small text-muted">
            Fitxer actual:
          </div>

          <div>
            ${escapeHtml(imatge.nameImg)}.${escapeHtml(imatge.extension)}
          </div>

        </div>


        <!-- ================================================== -->
        <!-- NOMBRE -->
        <!-- ================================================== -->

        <div class="col-md-6">

          <label
            for="imatge-${index}-nom"
            class="form-label">

            Nom
            <span class="text-danger">*</span>

          </label>

          <input
            type="text"
            class="form-control"
            id="imatge-${index}-nom"
            name="imatges[${index}][nom]"
            value="${escapeHtmlAttribute(imatge.nom)}"
            required>

        </div>


        <!-- ================================================== -->
        <!-- ALT -->
        <!-- ================================================== -->

        <div class="col-12">

          <label
            for="imatge-${index}-alt"
            class="form-label">

            Descripció de la imatge

          </label>

          <textarea
            class="form-control"
            id="imatge-${index}-alt"
            name="imatges[${index}][alt]"
            rows="3">${escapeHtml(imatge.alt ?? '')}</textarea>

        </div>

                <hr>

        <!-- ================================================== -->
        <!-- DATA IMATGE -->
        <!-- ================================================== -->

        <div class="col-md-4">

          <label
            for="imatge-${index}-dataImatge"
            class="form-label">

            Data imatge (automàtic)

          </label>

          <input
            type="datetime-local"
            class="form-control"
            id="imatge-${index}-dataImatge"
            name="imatges[${index}][dataImatge]"
            value="${formatDatetimeLocal(imatge.dataImatge)}">

        </div>

        <!-- ================================================== -->
        <!-- ANY -->
        <!-- ================================================== -->

        <div class="col-md-4">

          <label
            for="imatge-${index}-any"
            class="form-label">

            Any (opcional)

          </label>

          <input
            type="number"
            class="form-control"
            id="imatge-${index}-any"
            name="imatges[${index}][any]"
            value="${imatge.any ?? ''}"
            min="1900"
            max="2040">

        </div>

        <hr>


      </div>

    </div>

  `;
    container.appendChild(bloque);
    // ------------------------------------------------------------
    // Eliminar
    // ------------------------------------------------------------
    const btnEliminar = bloque.querySelector('.btnEliminarImatge');
    btnEliminar?.addEventListener('click', ()=>{
        bloque.remove();
        actualizarNumeracionImatges(container);
    });
}
// ============================================================
// BLOQUE IMAGEN NUEVA
// ============================================================
function crearBloqueImatge(container) {
    const index = container.children.length;
    const bloque = document.createElement('div');
    bloque.className = 'col-12';
    bloque.innerHTML = `

    <div class="card">

      <div class="card-header d-flex justify-content-between align-items-center">

        <strong>
          Imatge ${index + 1}
        </strong>

        <button
          type="button"
          class="btn btn-sm btn-outline-danger btnEliminarImatge">
          Eliminar
        </button>

      </div>


      <div class="card-body row g-3">


        <!-- ================================================== -->
        <!-- ARCHIVO -->
        <!-- ================================================== -->

        <div class="col-md-6">

          <label
            for="imatge-${index}-file"
            class="form-label">

            Fitxer
            <span class="text-danger">*</span>

          </label>

          <input
            type="file"
            class="form-control"
            id="imatge-${index}-file"
            name="imatges[${index}][file]"
            accept="image/jpeg,image/png"
            required>

        </div>


        <!-- ================================================== -->
        <!-- NOMBRE -->
        <!-- ================================================== -->

        <div class="col-md-6">

          <label
            for="imatge-${index}-nom"
            class="form-label">

            Nom
            <span class="text-danger">*</span>

          </label>

          <input
            type="text"
            class="form-control"
            id="imatge-${index}-nom"
            name="imatges[${index}][nom]"
            required>

        </div>


        <!-- ================================================== -->
        <!-- ALT -->
        <!-- ================================================== -->

        <div class="col-12">

          <label
            for="imatge-${index}-alt"
            class="form-label">

            Descripció de la imatge

          </label>

          <textarea
            class="form-control"
            id="imatge-${index}-alt"
            name="imatges[${index}][alt]"
            rows="3"></textarea>

        </div>

                <hr>

        <!-- ================================================== -->
        <!-- DATA IMATGE -->
        <!-- ================================================== -->

        <div class="col-md-4">

          <label
            for="imatge-${index}-dataImatge"
            class="form-label">

            Data imatge (automàtic)

          </label>

          <input
            type="datetime-local"
            class="form-control"
            id="imatge-${index}-dataImatge"
            name="imatges[${index}][dataImatge]">

        </div>

        <!-- ================================================== -->
        <!-- ANY -->
        <!-- ================================================== -->

        <div class="col-md-4">

          <label
            for="imatge-${index}-any"
            class="form-label">

            Any (opcional)

          </label>

          <input
            type="number"
            class="form-control"
            id="imatge-${index}-any"
            name="imatges[${index}][any]"
            min="1900"
            max="2040">

        </div>

        <hr>


      </div>

    </div>

  `;
    container.appendChild(bloque);
    // ------------------------------------------------------------
    // Eliminar
    // ------------------------------------------------------------
    const btnEliminar = bloque.querySelector('.btnEliminarImatge');
    btnEliminar?.addEventListener('click', ()=>{
        bloque.remove();
        actualizarNumeracionImatges(container);
    });
}
// ============================================================
// ACTUALIZAR NUMERACIÓN E ÍNDICES
// ============================================================
function actualizarNumeracionImatges(container) {
    const blocs = container.children;
    Array.from(blocs).forEach((bloc, index)=>{
        const card = bloc.querySelector('.card');
        if (!card) {
            return;
        }
        // --------------------------------------------------------
        // Título
        // --------------------------------------------------------
        const header = card.querySelector('.card-header strong');
        if (header) {
            header.textContent = `Imatge ${index + 1}`;
        }
        // --------------------------------------------------------
        // Actualizar names
        // --------------------------------------------------------
        const inputs = card.querySelectorAll('[name]');
        inputs.forEach((element)=>{
            const input = element;
            const name = input.getAttribute('name');
            if (!name) {
                return;
            }
            input.setAttribute('name', name.replace(/^imatges\[\d+\]/, `imatges[${index}]`));
        });
        // --------------------------------------------------------
        // Actualizar IDs
        // --------------------------------------------------------
        const elementsWithId = card.querySelectorAll('[id]');
        elementsWithId.forEach((element)=>{
            const htmlElement = element;
            const currentId = htmlElement.id;
            htmlElement.id = currentId.replace(/imatge-\d+/, `imatge-${index}`);
        });
        // --------------------------------------------------------
        // Actualizar "for" de labels
        // --------------------------------------------------------
        const labels = card.querySelectorAll('label[for]');
        labels.forEach((label)=>{
            const htmlLabel = label;
            htmlLabel.htmlFor = htmlLabel.htmlFor.replace(/imatge-\d+/, `imatge-${index}`);
        });
    });
}
// ============================================================
// ESCAPAR HTML
// ============================================================
function escapeHtml(value) {
    return value.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#039;');
}
// ============================================================
// ESCAPAR ATRIBUTO HTML
// ============================================================
function escapeHtmlAttribute(value) {
    return escapeHtml(value);
}
function formatDatetimeLocal(value) {
    if (!value) {
        return '';
    }
    return value.replace(' ', 'T').slice(0, 16);
}
