function renderPressupost(pressupost) {
    const container = document.getElementById('fitxaPressupost');
    if (!container) return;
    if (!pressupost) {
        container.innerHTML = `<p>No s'ha trobat el pressupost</p>`;
        return;
    }
    container.innerHTML = `
    <div class="card shadow-sm border-0">

      <!-- HEADER -->
      <div class="card-header bg-dark text-white d-flex justify-content-between">
        <div>
          <strong>Pressupost</strong> #${pressupost.id.slice(0, 8)}
        </div>

        <div class="text-end">
           <a
          href="/gestio/comptabilitat/modifica-pressupost/${pressupost.id}"
          class="btn btn-secondary btn-sm">
          Modifica pressupost
        </a>

        </div>
      </div>

      <div class="card-body">
        <div class="col-md-4" style="margin-bottom:25px">
            <span class="badge bg-primary">
               ${pressupost.estat ?? 'Sense estat'}
            </span>
          </div>

        <!-- TITOL -->
        <h4 class="mb-3">${pressupost.concepte}</h4>

        <div class="row g-3">

          <!-- IMPORT -->
          <div class="col-md-4">
            <div class="p-3 bg-light rounded">
              <div class="text-muted small">Import</div>
              <div class="fs-5 fw-bold text-success">
                ${formatMoney(pressupost.import)}
              </div>
            </div>
          </div>

          <!-- DATA -->
          <div class="col-md-4">
            <div class="p-3 bg-light rounded">
              <div class="text-muted small">Data</div>
              <div class="fw-semibold">
                ${formatDate(pressupost.data)}
              </div>
            </div>
          </div>

          <!-- ANY -->
          <div class="col-md-4">
            <div class="p-3 bg-light rounded">
              <div class="text-muted small">Any</div>
              <div class="fw-semibold">
                ${pressupost.any ?? '-'}
              </div>
            </div>
          </div>

          <!-- CLIENT -->
          <div class="col-md-6">
            <div class="p-3 bg-light rounded">
              <div class="text-muted small">Client</div>
              <div class="fw-semibold">
                ${pressupost.clientNom} ${pressupost.clientCognoms ?? ''}
              </div>
              <div class="small text-muted">
                ${pressupost.clientEmail ?? ''}
              </div>
              <div class="small text-muted">
                ${pressupost.clientEmpresa ?? ''}
              </div>
            </div>
          </div>

          <!-- PRODUCTE / SERVEI -->
          <div class="col-md-6">
            <div class="p-3 bg-light rounded">
              <div class="text-muted small">Servei</div>
              <div class="fw-semibold">
                ${pressupost.producte ?? '-'}
              </div>
            </div>
          </div>

        </div>
      </div>

            <div class="card-footer text-muted small">
              <div>
                Data d'alta: ${pressupost.created_at ? formatDate(pressupost.created_at) : '—'}
              </div>
              <div>
                Darrera actualització: ${pressupost.modified_at ? formatDate(pressupost.modified_at) : '—'}
              </div>
            </div>

    </div>
  `;
    container.style.display = 'block';
}
