// Generador PDF por idioma
async function generatePDF(invoiceId, lang, fileName, btn) {
    const prevLabel = btn?.textContent;
    if (btn) {
        btn.disabled = true;
        btn.textContent = 'Generant...';
    }
    try {
        const endpoint = _utils_apiUrls__WEBPACK_IMPORTED_MODULE_3__.API_URLS.GET.INVOICE_PDF(invoiceId, lang);
        const response = await fetch(endpoint, {
            credentials: 'include'
        });
        if (!response.ok) {
            throw new Error(`HTTP ${response.status}`);
        }
        const blob = await response.blob();
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = fileName || `invoice_${invoiceId}_${lang}.pdf`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
    } catch (e) {
        /* eslint-disable */ console.error(...oo_tx(`2810526662_44_4_44_48_11`, 'Error al generar el PDF:', e));
        alert("No s'ha pogut generar el PDF.");
    } finally{
        if (btn) {
            btn.disabled = false;
            btn.textContent = prevLabel || 'PDF';
        }
    }
}
