function procesarXML(xml) {
    const items = Array.from(xml.querySelectorAll('item'));
    return items.map((item)=>{
        const title = item.querySelector('title')?.textContent || 'Sin título';
        const link = item.querySelector('link')?.textContent || '#';
        const description = item.querySelector('description')?.textContent || '';
        const pubDate = item.querySelector('pubDate')?.textContent || '';
        return {
            title,
            link,
            description,
            date: pubDate
        };
    });
}
function lectorFeeds(url, targetElement) {
    const container = document.getElementById(targetElement);
    if (!container) return;
    container.innerHTML = '<p>Cargando...</p>';
    fetch(`/api/lector-rss/get/?url=${encodeURIComponent(url)}`).then((response)=>{
        const contentType = response.headers.get('Content-Type');
        if (contentType && contentType.includes('application/json')) {
            return response.json();
        } else {
            return response.text();
        }
    }).then((data)=>{
        if (typeof data === 'string') {
            const parser = new DOMParser();
            const xmlDoc = parser.parseFromString(data, 'application/xml');
            data = procesarXML(xmlDoc); // Asegúrate de que procesarXML devuelva FeedItem[]
        }
        let html = '<ul>';
        data.forEach((item)=>{
            html += `
          <li>
              <a href="${item.link}" target="_blank">${item.title}</a>
              <p><strong>${item.date}</strong></p>
              <p>${item.description}</p>
          </li>`;
        });
        html += '</ul>';
        const container = document.getElementById(targetElement);
        if (container) {
            container.innerHTML = html;
        }
    }).catch((error)=>{
        /* eslint-disable */ console.error(...oo_tx(`4239235890_103_6_103_62_11`, `Error al obtener el feed: ${url}`, error));
        const container = document.getElementById(targetElement);
        if (container) {
            container.innerHTML = '<p>Error al cargar el feed.</p>';
        }
    });
}
