    const descripcioInput = formWrapper.querySelector('#newCiutatDescripcio');
    const createBtn = formWrapper.querySelector('#createCiutatBtn');
    const message = formWrapper.querySelector('#createCiutatMessage');
    // Reutilitza la llista de paisos ja carregada per al select de país de l'autor
