/** Espera a que exista un trix-editor vinculado a un input concreto y devuelve ese editor */ async function getTrixEditorForInput(inputId, timeoutMs = 2000) {
    const start = performance.now();
    while(performance.now() - start < timeoutMs){
        const editor = document.querySelector(`trix-editor[input="${inputId}"]`);
        if (editor && editor.editor) return editor;
        await new Promise((r)=>setTimeout(r, 50));
    }
    throw new Error(`Trix editor no inicializado para input="${inputId}"`);
}
/** Carga HTML en el editor Trix (y sincroniza el hidden input) de forma robusta */ async function setTrixHTML(inputId, html) {
    const safe = html ?? '';
    const hidden = document.getElementById(inputId);
    if (hidden) hidden.value = safe; // asegura el valor en el hidden
    try {
        const editorEl = await getTrixEditorForInput(inputId);
        editorEl.editor.loadHTML(safe);
    } catch  {
    // Si no logramos coger el editor a tiempo, al menos queda el hidden con el valor
    }
}


